#!/usr/bin/env bash
#
# Provisioning wizard: walks the owner through every human-only go-live step
# for one environment, verifying each before moving on
# (docs/runbooks/provisioning.md, docs/spec/operations.md sections 2, 5, 8).
#
#   scripts/provision.sh staging               # the staging half
#   scripts/provision.sh production            # the production half
#   scripts/provision.sh staging --dry-run     # rehearse against fakes only
#
# Safe to rerun: each stage checks what already exists and only creates what
# is missing. Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: the Finders Eaters go-live steps (docs/runbooks/provisioning.md).
# ──────────────────────────────────────────────────────────────────────────

here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
assets="$here/provision"
cd "$here/.."   # gh resolves the repository from the working directory

usage() {
  echo "usage: scripts/provision.sh staging|production [--dry-run]" >&2
  exit 2
}

ENVIRONMENT="" DRY_RUN=false
for arg in "$@"; do
  case "$arg" in
    staging | production) ENVIRONMENT="$arg" ;;
    --dry-run) DRY_RUN=true ;;
    *) usage ;;
  esac
done
[[ -n "$ENVIRONMENT" ]] || usage

# An unexpected failure stops the wizard (set -e); say where, never silently.
set -E
trap 'printf "\n  %s✗ Stopped: a command failed at line %s of scripts/provision.sh (see above). Rerun when fixed.%s\n" "$RED" "$LINENO" "$RESET" >&2' ERR

# Values the wizard remembers between runs (Enter keeps them) live outside the
# repo, readable only by the owner. A dry run keeps everything in a scratch
# directory and puts the fakes first on PATH, so no real CLI is ever called.
umask 077
if $DRY_RUN; then
  PROVISION_FAKE_STATE="${PROVISION_FAKE_STATE:-$(mktemp -d)}"
  export PROVISION_FAKE_STATE
  PATH="$assets/fakes:$PATH"
  ENV_FILE="$PROVISION_FAKE_STATE/provision.env"
else
  ENV_FILE="${PROVISION_ENV_FILE:-${XDG_CONFIG_HOME:-$HOME/.config}/finderseaters/provision.env}"
  mkdir -p "$(dirname "$ENV_FILE")"
fi
POLL_SECONDS="${PROVISION_POLL_SECONDS:-5}"

if [[ "$ENVIRONMENT" == staging ]]; then
  APP=finders-eaters-staging FLY_CONFIG=fly.staging.toml BRANCH=develop NEON_BRANCH=staging
  WORKFLOW=deploy-staging.yml UPPER=STAGING HOST_SUFFIX=-staging
  TOTAL_STAGES=9
else
  APP=finders-eaters FLY_CONFIG=fly.toml BRANCH=main NEON_BRANCH=main
  WORKFLOW=deploy-production.yml UPPER=PRODUCTION HOST_SUFFIX=""
  TOTAL_STAGES=12
fi
NEON_PROJECT_NAME=finders-eaters
NEON_REGION=aws-eu-west-2 # AWS London
RESTORE_WINDOW_SECONDS=604800 # 7 days
BACKUP_BUCKET=finders-eaters-backups

# ── helpers ───────────────────────────────────────────────────────────────

ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die() {
  printf '\n  %s✗ %s%s\n' "$RED" "$1" "$RESET" >&2
  note "Nothing after this point was done. Fix it, then rerun: scripts/provision.sh $ENVIRONMENT"
  exit 1
}

# until_ok "what" CHECK...: runs CHECK until it succeeds, offering a retry
# after each failure. Declining stops the wizard.
until_ok() {
  local what="$1"
  shift
  until "$@"; do
    warn "$what: not done yet."
    confirm "Check again?" || die "$what was not verified."
  done
  ok "$what"
}

# ask_required KEY "Prompt" [PATTERN]: ask until the answer is non-empty (and
# matches PATTERN, when given).
ask_required() {
  local key="$1" prompt="$2" pattern="${3:-.}"
  while true; do
    ask "$key" "$prompt"
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "That doesn't look right; try again."
  done
}
ask_secret_required() {
  local key="$1" prompt="$2"
  while true; do
    ask_secret "$key" "$prompt"
    [[ -n "${!key}" ]] && return 0
    warn "Nothing was pasted; try again."
  done
}

# remembered KEY: the value saved by an earlier run, or nothing.
remembered() { _existing "$1" || true; }

# generated KEY: the remembered value, or a new random one saved for next time.
generated() {
  local value
  value="$(remembered "$1")"
  if [[ -z "$value" ]]; then
    value="$(openssl rand -hex 32)"
    write_env "$1" "$value" >/dev/null
  fi
  printf '%s' "$value"
}

has_command() { command -v "$1" >/dev/null 2>&1; }

gh_has_secret() { gh secret list --json name | jq -e --arg n "$1" 'any(.[]; .name == $n)' >/dev/null; }

# set_secret NAME VALUE and set_var NAME VALUE replace the library's versions,
# which carry on past a gh failure. Stage 1 has checked gh is signed in, so a
# failure here is real: it stops the wizard. Each value is then checked in
# GitHub before moving on.
set_secret() {
  local name="$1" value="$2"
  printf '%s' "$value" | gh secret set "$name" >/dev/null ||
    die "Setting GitHub secret $name failed (see the error above)."
  until_ok "GitHub secret $name is set" gh_has_secret "$name"
  WRITTEN_SECRET+=("$name")
}
set_var() {
  local name="$1" value="$2"
  gh variable set "$name" --body "$value" >/dev/null ||
    die "Setting GitHub variable $name failed (see the error above)."
  until_ok "GitHub variable $name is $value" gh_var_is "$name" "$value"
}
gh_var_is() { # NAME VALUE
  gh variable list --json name,value |
    jq -e --arg n "$1" --arg v "$2" 'any(.[]; .name == $n and .value == $v)' >/dev/null
}

fly_app_exists() { fly apps list --json | jq -e --arg a "$1" 'any(.[]; (.Name // .name) == $a)' >/dev/null; }

fly_secret_names() { fly secrets list -a "$APP" --json | jq -r '.[] | (.Name // .name)' | sort | tr '\n' ' '; }

neon_project() { neonctl projects get "$NEON_PROJECT_ID" --output json | jq '.project // .'; }

neon_has_branch() {
  neonctl branches list --project-id "$NEON_PROJECT_ID" --output json |
    jq -e --arg b "$1" 'any((.branches // .)[]; .name == $b)' >/dev/null
}

neon_url() { # BRANCH [--pooled]
  neonctl connection-string "$1" --project-id "$NEON_PROJECT_ID" ${2:+"$2"}
}

can_connect() { [[ "$(psql "$1" -At -c 'select 1' 2>/dev/null)" == 1 ]]; }

# health_ok URL: the server's deep /health says ok (docs/runbooks/deploy.md).
health_ok() {
  local body
  body="$(curl -sS --max-time 30 "$1" 2>/dev/null)" || return 1
  [[ "$body" == *'"status":"ok"'* ]] || return 1
  ok "$1 → ok"
}

# scrub TEXT: TEXT with the Cloudflare account ID and token blanked out.
scrub() {
  local text="$1"
  [[ -n "${CLOUDFLARE_ACCOUNT_ID:-}" ]] && text="${text//"$CLOUDFLARE_ACCOUNT_ID"/<account id>}"
  [[ -n "${CLOUDFLARE_API_TOKEN:-}" ]] && text="${text//"$CLOUDFLARE_API_TOKEN"/<token>}"
  printf '%s' "$text"
}

# clef_check: one dev-set Clef request (golden line L01, never a held-out
# line) to Workers AI with the pasted account ID and token. Both travel to
# curl on stdin, so neither shows in a process list, and neither is printed.
clef_check() {
  local body err code summary
  body="$(mktemp)" err="$(mktemp)"
  code="$(printf 'url = "https://api.cloudflare.com/client/v4/accounts/%s/ai/run/@cf/cloudflare/clef"\nheader = "Authorization: Bearer %s"\n' \
    "$CLOUDFLARE_ACCOUNT_ID" "$CLOUDFLARE_API_TOKEN" |
    curl -sS --max-time 30 -o "$body" -w '%{http_code}' -K - \
      -H 'Content-Type: application/json' --data-binary @"$assets/clef-dev-request.json" 2>"$err")" || true
  if [[ "$code" == 200 ]] &&
    summary="$(jq -er 'select(.success == true) | .result.answers.role
      | "role = \(.choice) (p \(.probabilities[.choice]))"' "$body" 2>/dev/null)"; then
    ok "Clef answered dev line L01 (\"200g basmati rice\"): $summary"
    rm -f "$body" "$err"
    return 0
  fi
  warn "Workers AI did not answer (HTTP ${code:-none})."
  [[ -s "$err" ]] && note "$(scrub "$(cat "$err")")"
  [[ -s "$body" ]] && note "$(scrub "$(jq -r '[.errors[]? | "\(.code): \(.message)"] | join("; ")' "$body" 2>/dev/null || true)")"
  rm -f "$body" "$err"
  return 1
}

# latest_run: the newest run id of this environment's deploy workflow, or 0.
latest_run() {
  gh run list --workflow "$WORKFLOW" --branch "$BRANCH" --limit 1 --json databaseId |
    jq -r '.[0].databaseId // 0'
}

# deploy_now: dispatch the deploy workflow on its branch, wait for it, then
# check /health on the app's fly.dev address.
deploy_now() {
  local before run tries=0
  before="$(latest_run)"
  gh workflow run "$WORKFLOW" --ref "$BRANCH" || die "Could not start $WORKFLOW on $BRANCH."
  run="$before"
  while [[ "$run" == "$before" ]]; do
    if ((++tries > 60)); then die "The $WORKFLOW run did not appear in GitHub Actions."; fi
    sleep "$POLL_SECONDS"
    run="$(latest_run)"
  done
  say "Following run $run (gh run view $run --log for the full log)..."
  gh run watch "$run" --exit-status || die "The $ENVIRONMENT deploy failed. Read it with: gh run view $run --log-failed"
  until_ok "$ENVIRONMENT answers /health" health_ok "https://$APP.fly.dev/health"
}

# ── stages ────────────────────────────────────────────────────────────────

if $DRY_RUN; then
  banner "Provision $ENVIRONMENT (DRY RUN: fakes only, nothing real is touched)"
  note "Rehearsal state: $PROVISION_FAKE_STATE"
else
  banner "Provision $ENVIRONMENT"
fi

stage "Tools and sign-ins"
say "The wizard drives these CLIs. It checks each is installed and signed in."
tools=(fly gh neonctl psql curl jq openssl)
[[ "$ENVIRONMENT" == production ]] && tools+=(aws)
missing=()
for tool in "${tools[@]}"; do has_command "$tool" || missing+=("$tool"); done
if ((${#missing[@]})); then
  warn "Missing: ${missing[*]}"
  note "macOS: brew install flyctl gh neonctl libpq jq awscli (libpq provides psql)"
  die "Install the missing tools, then rerun."
fi
ok "Installed: ${tools[*]}"
until_ok "Signed in to Fly (fly auth login)" fly auth whoami
until_ok "Signed in to GitHub (gh auth login)" gh auth status
until_ok "Signed in to Neon (neonctl auth)" neonctl me --output json

stage "Neon project and restore window"
say "One Neon project in AWS London holds production (root branch main) and"
say "staging (branch staging). Its restore window must be 7 days."
NEON_PROJECT_ID="$(remembered NEON_PROJECT_ID)"
if [[ -z "$NEON_PROJECT_ID" ]]; then
  NEON_PROJECT_ID="$(neonctl projects list --output json |
    jq -r --arg n "$NEON_PROJECT_NAME" '[(.projects // .)[] | select(.name == $n)][0].id // empty')"
fi
if [[ -z "$NEON_PROJECT_ID" ]]; then
  confirm "Create the Neon project $NEON_PROJECT_NAME in AWS London (Postgres 17)?" ||
    die "The Neon project is needed for everything after this."
  NEON_PROJECT_ID="$(neonctl projects create --name "$NEON_PROJECT_NAME" --region-id "$NEON_REGION" \
    --pg-version 17 --output json | jq -r '(.project // .).id')"
fi
write_env NEON_PROJECT_ID "$NEON_PROJECT_ID"
project="$(neon_project)" || die "Neon project $NEON_PROJECT_ID is not reachable."
[[ "$(jq -r .region_id <<<"$project")" == "$NEON_REGION" ]] ||
  die "Neon project $NEON_PROJECT_ID is not in $NEON_REGION (AWS London)."
[[ "$(jq -r .pg_version <<<"$project")" == 17 ]] || die "Neon project $NEON_PROJECT_ID is not Postgres 17."
ok "Neon project $NEON_PROJECT_ID: AWS London, Postgres 17"
restore_window_ok() {
  [[ "$(neon_project | jq -r '.history_retention_seconds')" == "$RESTORE_WINDOW_SECONDS" ]]
}
if ! restore_window_ok; then
  open_url "https://console.neon.tech/app/projects/$NEON_PROJECT_ID/settings"
  step "In the project's Settings, find the restore window (history retention)."
  step "Set it to 7 days and save."
  pause "Press Enter when it is saved."
fi
until_ok "Restore window is 7 days" restore_window_ok

stage "Neon branch $NEON_BRANCH and its connection strings"
if ! neon_has_branch "$NEON_BRANCH"; then
  confirm "Create the Neon branch $NEON_BRANCH from main, with its own compute?" ||
    die "$ENVIRONMENT needs its own Neon branch."
  neonctl branches create --project-id "$NEON_PROJECT_ID" --name "$NEON_BRANCH" --parent main \
    --output json >/dev/null
fi
until_ok "Neon branch $NEON_BRANCH exists" neon_has_branch "$NEON_BRANCH"
DATABASE_URL="$(neon_url "$NEON_BRANCH" --pooled)"
DATABASE_URL_DIRECT="$(neon_url "$NEON_BRANCH")"
until_ok "Pooled connection (DATABASE_URL) works" can_connect "$DATABASE_URL"
until_ok "Direct connection (DATABASE_URL_DIRECT) works" can_connect "$DATABASE_URL_DIRECT"
note "The URLs are read from Neon each run and are not saved locally."

if [[ "$ENVIRONMENT" == production ]]; then
  stage "The read-only backup role"
  say "The nightly backup logs in as 'backup', which can read every table and"
  say "write nothing (docs/spec/operations.md section 5.2)."
  BACKUP_ROLE_PASSWORD="$(generated BACKUP_ROLE_PASSWORD)"
  sed "s/__PASSWORD__/$BACKUP_ROLE_PASSWORD/g" "$assets/backup-role.sql" |
    psql "$DATABASE_URL_DIRECT" -v ON_ERROR_STOP=1 -q >/dev/null ||
    die "Creating the backup role failed (see the error above)."
  BACKUP_DATABASE_URL="$(sed -E "s#^(postgres(ql)?://)[^@]+@#\1backup:$BACKUP_ROLE_PASSWORD@#" <<<"$DATABASE_URL_DIRECT")"
  backup_role_ok() {
    [[ "$(psql "$BACKUP_DATABASE_URL" -At -c "$(cat "$assets/backup-role-check.sql")" 2>/dev/null)" == t ]]
  }
  until_ok "backup reads everything and can write nothing" backup_role_ok
  set_secret BACKUP_DATABASE_URL "$BACKUP_DATABASE_URL"

  stage "Tigris bucket for backups"
  say "Nightly dumps go to the private bucket $BACKUP_BUCKET, with a key that"
  say "can reach only that bucket."
  BACKUP_S3_ENDPOINT="$(remembered BACKUP_S3_ENDPOINT)"
  BACKUP_S3_ENDPOINT="${BACKUP_S3_ENDPOINT:-https://fly.storage.tigris.dev}"
  BACKUP_S3_ACCESS_KEY_ID="$(remembered BACKUP_S3_ACCESS_KEY_ID)"
  BACKUP_S3_SECRET_ACCESS_KEY="$(remembered BACKUP_S3_SECRET_ACCESS_KEY)"
  tigris() {
    AWS_ACCESS_KEY_ID="$BACKUP_S3_ACCESS_KEY_ID" AWS_SECRET_ACCESS_KEY="$BACKUP_S3_SECRET_ACCESS_KEY" \
      AWS_REGION=auto aws "$@" --endpoint-url "$BACKUP_S3_ENDPOINT"
  }
  bucket_ok() { tigris s3api head-bucket --bucket "$BACKUP_BUCKET" >/dev/null 2>&1; }
  if [[ -z "$BACKUP_S3_ACCESS_KEY_ID" ]] || ! bucket_ok; then
    say "If the bucket does not exist yet, the wizard creates it with"
    say "'fly storage create', which prints a key scoped to that bucket once."
    if confirm "Create the Tigris bucket $BACKUP_BUCKET now? (No if it already exists)"; then
      FLY_ORG="$(remembered FLY_ORG)"
      [[ -n "$FLY_ORG" ]] || ask_required FLY_ORG "Fly organisation slug ('personal' for your own account):" '^[a-z0-9-]+$'
      write_env FLY_ORG "$FLY_ORG"
      fly storage create --name "$BACKUP_BUCKET" --org "$FLY_ORG" || die "fly storage create failed."
      step "Copy the access key ID and secret printed above into the prompts below."
    else
      open_url "https://console.tigris.dev"
      step "Create an access key with Editor access to $BACKUP_BUCKET only."
    fi
    ask_secret_required BACKUP_S3_ACCESS_KEY_ID "Paste the access key ID (AWS_ACCESS_KEY_ID, hidden):"
    ask_secret_required BACKUP_S3_SECRET_ACCESS_KEY "Paste the secret (AWS_SECRET_ACCESS_KEY, hidden):"
  fi
  until_ok "The key reaches bucket $BACKUP_BUCKET" bucket_ok
  write_env BACKUP_S3_ENDPOINT "$BACKUP_S3_ENDPOINT"
  write_env BACKUP_S3_ACCESS_KEY_ID "$BACKUP_S3_ACCESS_KEY_ID"
  write_env BACKUP_S3_SECRET_ACCESS_KEY "$BACKUP_S3_SECRET_ACCESS_KEY"
  tigris s3api put-bucket-lifecycle-configuration --bucket "$BACKUP_BUCKET" \
    --lifecycle-configuration "file://$assets/tigris-lifecycle.json" || die "Setting the lifecycle rules failed."
  lifecycle_ok() {
    tigris s3api get-bucket-lifecycle-configuration --bucket "$BACKUP_BUCKET" | jq -e '
      [.Rules[] | select(.Status == "Enabled") | {p: .Filter.Prefix, d: .Expiration.Days}]
      | (index({p: "daily/", d: 35}) != null) and (index({p: "monthly/", d: 400}) != null)' >/dev/null
  }
  until_ok "Lifecycle: daily/ expires after 35 days, monthly/ after 400" lifecycle_ok
  probe="probe/provision-$(date -u +%Y%m%dT%H%M%SZ)"
  write_read_ok() {
    echo probe | tigris s3 cp - "s3://$BACKUP_BUCKET/$probe" >/dev/null &&
      [[ "$(tigris s3 cp "s3://$BACKUP_BUCKET/$probe" -)" == probe ]] &&
      tigris s3 rm "s3://$BACKUP_BUCKET/$probe" >/dev/null
  }
  until_ok "The key can write, read and delete in the bucket" write_read_ok
  set_secret BACKUP_S3_ACCESS_KEY_ID "$BACKUP_S3_ACCESS_KEY_ID"
  set_secret BACKUP_S3_SECRET_ACCESS_KEY "$BACKUP_S3_SECRET_ACCESS_KEY"
  set_var BACKUP_S3_ENDPOINT "$BACKUP_S3_ENDPOINT"
  set_var BACKUP_S3_BUCKET "$BACKUP_BUCKET"
fi

stage "Cloudflare Workers AI (hosted Clef)"
say "Both apps and CI call Clef with your Cloudflare account ID and a token"
say "scoped to Workers AI (docs/adr/0002-clef-on-workers-ai.md)."
open_url "https://dash.cloudflare.com/?to=/:account/ai/workers-ai"
step "Workers AI → 'Use REST API': copy the account ID, then create a Workers AI API token."
note "Both are entered hidden and never printed. Enter keeps the saved ones."
while true; do
  ask_secret_required CLOUDFLARE_ACCOUNT_ID "Paste the Cloudflare account ID (hidden):"
  ask_secret_required CLOUDFLARE_API_TOKEN "Paste the Workers AI API token (hidden):"
  say "Checking with one dev-set Clef request..."
  clef_check && break
  confirm "Paste new values and try again?" || die "The Cloudflare token was not verified."
done
write_env CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
write_env CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
set_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
set_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"

stage "Fly app $APP"
FLY_ORG="$(remembered FLY_ORG)"
[[ -n "$FLY_ORG" ]] || ask_required FLY_ORG "Fly organisation slug ('personal' for your own account):" '^[a-z0-9-]+$'
write_env FLY_ORG "$FLY_ORG"
if ! fly_app_exists "$APP"; then
  confirm "Create the Fly app $APP in org $FLY_ORG? (lhr, configured by $FLY_CONFIG)" ||
    die "$ENVIRONMENT needs its Fly app."
  fly apps create "$APP" --org "$FLY_ORG"
fi
until_ok "Fly app $APP exists" fly_app_exists "$APP"

stage "Fly secrets for $APP"
SUBDOMAIN="$(remembered SUBDOMAIN)"
[[ -n "$SUBDOMAIN" ]] || ask_required SUBDOMAIN "Which subdomain of homeofed.com is production on (e.g. food)?" '^[a-z0-9-]+$'
write_env SUBDOMAIN "$SUBDOMAIN"
HOST="$SUBDOMAIN$HOST_SUFFIX.homeofed.com"
BETTER_AUTH_SECRET="$(generated "BETTER_AUTH_SECRET_$UPPER")"
say "Setting DATABASE_URL, DATABASE_URL_DIRECT, CLOUDFLARE_ACCOUNT_ID,"
say "CLOUDFLARE_API_TOKEN, BETTER_AUTH_SECRET and BETTER_AUTH_URL=https://$HOST."
note "Staged: they apply on the next deploy. Values go over stdin, never shown."
printf '%s\n' \
  "DATABASE_URL=$DATABASE_URL" \
  "DATABASE_URL_DIRECT=$DATABASE_URL_DIRECT" \
  "CLOUDFLARE_ACCOUNT_ID=$CLOUDFLARE_ACCOUNT_ID" \
  "CLOUDFLARE_API_TOKEN=$CLOUDFLARE_API_TOKEN" \
  "BETTER_AUTH_SECRET=$BETTER_AUTH_SECRET" \
  "BETTER_AUTH_URL=https://$HOST" |
  fly secrets import -a "$APP" --stage >/dev/null || die "fly secrets import failed."
secrets_ok() {
  [[ "$(fly_secret_names)" == "BETTER_AUTH_SECRET BETTER_AUTH_URL CLOUDFLARE_ACCOUNT_ID CLOUDFLARE_API_TOKEN DATABASE_URL DATABASE_URL_DIRECT " ]]
}
until_ok "$APP has its six secrets" secrets_ok

stage "GitHub secrets for $ENVIRONMENT deploys"
token_secret="FLY_API_TOKEN_$UPPER"
if ! gh_has_secret "$token_secret" || confirm "$token_secret is already set. Replace it with a new deploy token?"; then
  say "Creating a deploy token scoped to $APP and storing it straight in GitHub..."
  deploy_token="$(fly tokens create deploy -a "$APP")" || die "fly tokens create failed."
  set_secret "$token_secret" "$deploy_token"
  unset deploy_token
fi
until_ok "GitHub secret $token_secret is set" gh_has_secret "$token_secret"
if [[ "$ENVIRONMENT" == staging ]]; then
  set_secret STAGING_DATABASE_URL_DIRECT "$DATABASE_URL_DIRECT"
fi

stage "Switch $ENVIRONMENT deploys on and deploy"
deployed=false
if [[ "$ENVIRONMENT" == staging ]]; then
  say "Every push to develop will deploy staging. The wizard sets"
  say "DEPLOY_STAGING_ENABLED=true and runs the first deploy now."
  if confirm "Turn staging deploys on and deploy develop now?"; then
    set_var DEPLOY_STAGING_ENABLED true
    deploy_now
    deployed=true
  fi
else
  say "Production deploys fail closed until the Clef canary (#66) replaces the"
  say "placeholder step, so only switch them on once #66 is on main."
  if confirm "Is the Clef canary (#66) on main? Turn production deploys on and deploy main now?"; then
    set_var DEPLOY_PRODUCTION_ENABLED true
    deploy_now
    deployed=true
  fi
fi
if ! $deployed; then
  if health_ok "https://$APP.fly.dev/health"; then
    deployed=true
  else
    SKIPPED+=("$ENVIRONMENT deploys are off: rerun scripts/provision.sh $ENVIRONMENT to switch them on")
  fi
fi

stage "Custom domain $HOST"
if ! $deployed; then
  warn "$APP is not deployed yet, so the domain can't be checked."
  SKIPPED+=("custom domain $HOST: rerun once $ENVIRONMENT is deployed")
else
  if ! fly certs show "$HOST" -a "$APP" >/dev/null 2>&1; then
    confirm "Add the certificate for $HOST to $APP?" || die "$HOST needs a certificate on Fly."
    fly certs add "$HOST" -a "$APP" >/dev/null
  fi
  ok "Fly holds a certificate for $HOST"
  open_url "https://dash.cloudflare.com/?to=/:account/homeofed.com/dns/records"
  step "Add a CNAME record: name $SUBDOMAIN$HOST_SUFFIX, target $APP.fly.dev."
  step "Set Proxy status to 'DNS only' (grey cloud), so Fly can issue the certificate."
  note "Already there from an earlier run? Leave it as it is."
  pause "Press Enter when the record is saved."
  until_ok "https://$HOST answers /health (the certificate can take a few minutes)" health_ok "https://$HOST/health"
fi

if [[ "$ENVIRONMENT" == production ]]; then
  stage "Household and users"
  if ! $deployed; then
    warn "Production is not deployed yet; accounts are made on the running app."
    SKIPPED+=("household and users: rerun once production is deployed")
  else
    say "Accounts are made with the admin CLI on the running app"
    say "(docs/spec/auth.md section 4). Each first password is shown once: keep it."
    admin() { # ARGS...: run the admin CLI on the app over fly ssh
      fly ssh console -a "$APP" -C "node apps/server/src/cli.ts$(printf ' %q' "$@")"
    }
    HOUSEHOLD_ID="$(remembered HOUSEHOLD_ID)"
    if [[ -z "$HOUSEHOLD_ID" ]]; then
      ask_required HOUSEHOLD_NAME "Household name (e.g. The Barneses):"
      ask_required OWNER_EMAIL "Your email (you sign in with it):" '^[^@ ]+@[^@ ]+$'
      ask_required OWNER_NAME "Your first name:"
      confirm "Create the household \"$HOUSEHOLD_NAME\" with $OWNER_EMAIL?" || die "No household was created."
      output="$(admin household create --name "$HOUSEHOLD_NAME" --email "$OWNER_EMAIL" --user-name "$OWNER_NAME")" ||
        die "household create failed. If the email already exists, find the household id and rerun."
      printf '%s\n' "$output" | sed 's/^/    /'
      HOUSEHOLD_ID="$(sed -nE 's/.*\(id ([^,)]+), timezone.*/\1/p' <<<"$output")"
      [[ -n "$HOUSEHOLD_ID" ]] || die "Could not read the household id from the output above."
      write_env HOUSEHOLD_ID "$HOUSEHOLD_ID"
      pause "Press Enter once your first password is somewhere safe."
    fi
    ok "Household $HOUSEHOLD_ID"
    if [[ -z "$(remembered SECOND_USER_EMAIL)" ]]; then
      ask_required SECOND_USER_EMAIL "Second user's email:" '^[^@ ]+@[^@ ]+$'
      ask_required SECOND_USER_NAME "Second user's first name:"
      if output="$(admin user add --household "$HOUSEHOLD_ID" --email "$SECOND_USER_EMAIL" --name "$SECOND_USER_NAME" 2>&1)"; then
        printf '%s\n' "$output" | sed 's/^/    /'
        pause "Press Enter once their first password is somewhere safe."
      elif [[ "$output" != *"already exists"* ]]; then
        printf '%s\n' "$output" | sed 's/^/    /'
        die "user add failed."
      fi
      write_env SECOND_USER_EMAIL "$SECOND_USER_EMAIL"
    fi
    ok "Second user $(remembered SECOND_USER_EMAIL)"
  fi
fi

finish

